import { inject, Injectable } from '@angular/core';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import * as ItemActions from './item.actions';
import { NgrxTestService } from '../../../core/services/ngrx-test.service';
import { catchError, map, switchMap } from 'rxjs/operators';
import { of } from 'rxjs';

@Injectable()
export class ItemEffects {
  private actions$ = inject(Actions);
  private ngrxService = inject(NgrxTestService);

  loadItems$ = createEffect(() =>
    this.actions$.pipe(
      ofType(ItemActions.loadItems),
      switchMap(() =>
        this.ngrxService.loadItems().pipe(
          map((items) => ItemActions.loadItemsSuccess({ items })),
          catchError((err) => of(ItemActions.loadItemsFailure({ error: String(err) }))),
        ),
      ),
    ),
  );
}

import { Injectable } from '@angular/core';
import { transactions } from '../../../data/mock-transactions';
import { Transaction } from '../../../models/finance/transaction.model';

@Injectable({
  providedIn: 'root',
})
export class MockDataService {
  seedTransactions(): Transaction[] {
    try {
      const validatedTransactions = transactions.map((rowT) => {
        return {
          ...rowT,
          date: new Date(rowT.date),
        } as Transaction;
      });

      return validatedTransactions;
    } catch (error) {
      console.error('Error seeding transactions:', error);
    }
    return [];
  }
}

import { Injectable } from '@angular/core';
import { Item } from '../../models/inventory/item.model';
import { MOCK_ITEMS } from '../../data/mock-inventory-items';
import { delay, of } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class NgrxTestService {
  loadItems() {
    return of<Item[]>(MOCK_ITEMS).pipe(delay(800));
  }
}

