import { Component, Input, OnChanges, OnInit, SimpleChanges, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Transaction } from '../../../models/finance/transaction.model';
import { formatDate } from '../../../core/utils/date-utils';
import { MatIconModule } from '@angular/material/icon';
import { TransactionStateService } from '../../../core/services/finance/transaction-state.service';

@Component({
  selector: 'app-transaction-list',
  imports: [MatIconModule, CommonModule],
  templateUrl: './transaction-list.component.html',
  styleUrl: './transaction-list.component.scss',
})
export class TransactionListComponent implements OnInit, OnChanges {
  private transactionStateService = inject(TransactionStateService);
  @Input() transactions: Transaction[] = [];
  @Input() locale = 'de-DE';
  sortedTransactions: Transaction[] = [];
  currentSort: { key: keyof Transaction; asc: boolean } | null = null;

  expandedRows: Set<number> = new Set<number>();

  ngOnInit(): void {
    this.sortedTransactions = [...this.transactions];
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['transactions'] && !changes['transactions'].firstChange) {
      this.sortedTransactions = [...this.transactions];
      if (this.currentSort) {
        this.sortBy(this.currentSort.key, this.currentSort.asc);
      }
    }
  }

  // Format date with long style
  formattedDate(transaction: Transaction): string {
    if (transaction?.date) {
      return formatDate(transaction?.date, { style: 'long', locale: this.locale });
    }
    return 'NaN';
  }

  sortBy(field: keyof Transaction, asc?: boolean): void {
    const direction =
      asc !== undefined ? asc : this.currentSort?.key === field ? !this.currentSort.asc : true;
    this.currentSort = { key: field, asc: direction };

    this.sortedTransactions = [...this.sortedTransactions].sort((a, b) => {
      let valA = a[field];
      let valB = b[field];

      if (valA instanceof Date && valB instanceof Date) {
        valA = valA.getTime();
        valB = valB.getTime();
        return direction ? valA - valB : valB - valA;
      }

      if (typeof valA === 'number' && typeof valB === 'number') {
        return direction ? valA - valB : valB - valA;
      }

      return direction
        ? String(valA).localeCompare(String(valB))
        : String(valB).localeCompare(String(valA));
    });
  }

  getSortIcon(field: keyof Transaction): string {
    if (this.currentSort?.key === field) {
      return this.currentSort.asc ? 'arrow_upward' : 'arrow_downward';
    }
    return 'unfold_more';
  }

  // Format for mobile view - short date
  formattedShortDate(transaction: Transaction): string {
    if (transaction?.date) {
      return formatDate(transaction?.date, { style: 'short', locale: this.locale });
    }
    return 'NaN';
  }

  toggleRowExpand(transactionId: number): void {
    if (this.expandedRows.has(transactionId)) {
      this.expandedRows.delete(transactionId);
    } else {
      this.expandedRows.add(transactionId);
    }
  }

  isRowExpanded(transactionId: number): boolean {
    return this.expandedRows.has(transactionId);
  }

  getAmountClass(type: string): string {
    return type === 'income' ? 'amount-positive' : 'amount-negative';
  }

  /**
   * Selects a transaction when clicked
   * Updates the selected transaction in the TransactionStateService
   */
  selectTransaction(transaction: Transaction, event?: Event): void {
    if (event) {
      event.stopPropagation(); // Prevent other click events from firing
    }
    this.transactionStateService.selectTransaction(transaction);
  }
}

import { Component, DestroyRef, effect, inject, OnInit, signal } from '@angular/core';
import { TransactionService } from '../../../core/services/finance/transaction.service';
import { Transaction, TransactionSummary } from '../../../models/finance/transaction.model';
import { TransactionListComponent } from '../../../components/finance/transaction-list/transaction-list.component';
import { TotalsCardComponent } from '../../../components/finance/totals-card/totals-card.component';
import { FilterBarComponent } from '../../../components/finance/filter-bar/filter-bar.component';
import { catchError, of, tap } from 'rxjs';
import { MatDialog, MatDialogRef } from '@angular/material/dialog';
import { TransactionStateService } from '../../../core/services/finance/transaction-state.service';
import { TransactionDetailComponent } from './transaction-detail/transaction-detail.component';
//import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
  selector: 'app-transactions-page',
  imports: [TransactionListComponent, TotalsCardComponent, FilterBarComponent],
  templateUrl: './transactions-page.component.html',
  styleUrl: './transactions-page.component.scss',
})
export class TransactionsPageComponent implements OnInit {
  private transactionService = inject(TransactionService);
  private transactionStateService = inject(TransactionStateService);
  private destroyRef = inject(DestroyRef);
  private dialogRef: MatDialogRef<TransactionDetailComponent> | null = null;
  private dialog = inject(MatDialog);

  transactions = signal<Transaction[]>([]);
  transactionSummary = signal<TransactionSummary>({
    totalIncome: 0,
    totalExpense: 0,
    netBalance: 0,
  });

  constructor() {
    // Create an effect that watches for changes to the selected transaction
    effect(() => {
      const selectedTransaction = this.transactionStateService.selectedTransaction();
      console.log('Page effect:', selectedTransaction, this.dialogRef);
      if (selectedTransaction) {
        // Close any existing dialog first
        if (this.dialogRef) {
          this.dialogRef.close();
        }

        // Open the dialog with the selected transaction
        this.dialogRef = this.dialog.open(TransactionDetailComponent, {
          width: '800px',
          height: '500px',
          data: { transaction: selectedTransaction },
        });

        // When the dialog closes, clear the selected transaction
        this.dialogRef?.afterClosed().subscribe(() => {
          this.transactionStateService.clearSelectedTransaction();
        });
      }
    });
  }

  ngOnInit(): void {
    this.loadTransactions();
  }

  loadTransactions() {
    this.transactionService
      .getAll()
      .pipe(
        //takeUntilDestroyed(),
        tap((transactions: Transaction[]) => {
          this.transactions.set(transactions);
        }),
        catchError((err: Error) => {
          console.error('Failed to load transactions', err);
          return of([]);
        }),
      )
      .subscribe();
  }

  onFilterChanged(filter: { key: string; value: string }[]): void {
    console.log('onFilerChanged: ', filter);
    this.transactionService
      .searchByParam(filter)
      .pipe(
        //takeUntilDestroyed(),
        tap((transactions) => this.transactions.set(transactions)),
        catchError((err: Error) => {
          console.error('Failed to search transactions', err);
          return of([]);
        }),
      )
      .subscribe({
        next: (data) => console.log('onFilterChanged-Result - ', data),
      });
  }
}

