  if (req.url.includes(environment.rawgApiUrl!) && req.url.includes('/suggested')) {
    // DO NOTHING
    // Suggested endpoint already has the key in the service method (My dev key does not work! copied from real request)
  } else if (req.url.startsWith(environment.rawgApiUrl!)) {
    const clone = req.clone({
      params: req.params.set('key', environment.rawgApiKey!),
    });
    return next(clone);
  }

  return next(req);
}

createSelector(selectAllItems, selectCounts, (items, counts) =>
  items.map((item) => ({ item, count: counts[item.id] ?? 0 })),
)

createSelector(selectInventoryList, (entries) => {
  let weight = 0,
    value = 0,
    count = 0;
  for (const e of entries) {
    weight += e.item.weight * e.count;
    value += e.item.value * e.count;
    count += e.count;
  }
  return { weight, value, count };
})

